using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ApiTools
{
    /// <summary>Fetches JSON data from an external API endpoint.</summary>
    [McpServerTool, Description("Fetch JSON from an external API. Returns the raw JSON response body.")]
    public static async Task<string> FetchApi(
        IHttpClientFactory httpClientFactory,
        [Description("The full URL to fetch")] string url,
        CancellationToken cancellationToken = default)
    {
        using var client = httpClientFactory.CreateClient("api");
        using var response = await client.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return JsonSerializer.Serialize(json, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol;
using ModelContextProtocol.Server;

[McpServerPromptType]
public static class SummarizationPrompts
{
    [McpServerPrompt, Description("Generate a concise summary of the provided text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text to summarize")] string text,
        [Description("Optional maximum number of sentences")] int maxSentences = 3)
    {
        return
        [
            new(Role.User,
                $"""
                Summarize the following text in at most {maxSentences} sentence(s).
                Be concise and capture the key points.

                Text:
                {text}
                """)
        ];
    }
}

